const candidate = $json.candidates[0];
const parts = candidate.content.parts;

const functionCallPart = parts.find(p => p.functionCall);

if (!functionCallPart) {
  const textPart = parts.find(p => p.text);
  return {
    json: {
      direct_reply: textPart ? textPart.text : "Je n'ai pas compris votre demande.",
      needs_tool_call: false
    }
  };
}

const args = functionCallPart.functionCall.args;

const CITY_NORMALIZATION_MAP = {
  "marrakech": "Marrakesh",
  "marrakesh": "Marrakesh",
  "casablanca": "Casablanca",
  "casa": "Casablanca",
  "rabat": "Rabat",
  "agadir": "Agadir",
  "tanger": "Tanger",
  "tangier": "Tanger",
  "fes": "Fès",
  "fès": "Fès",
  "fez": "Fès"
};

function normalizeCity(rawCity) {
  if (!rawCity) return rawCity;
  const key = rawCity.trim().toLowerCase();
  return CITY_NORMALIZATION_MAP[key] || rawCity;
}

if (args.city) {
  args.city = normalizeCity(args.city);
}

const queryParts = [];
if (args.city) queryParts.push('city=' + encodeURIComponent(args.city));
if (args.property_type) queryParts.push('property_type=' + encodeURIComponent(args.property_type));
if (args.transaction_type) queryParts.push('transaction_type=' + encodeURIComponent(args.transaction_type));
if (args.price_max) queryParts.push('price_max=' + encodeURIComponent(args.price_max));
if (args.price_min) queryParts.push('price_min=' + encodeURIComponent(args.price_min));
if (args.bedrooms_min) queryParts.push('bedrooms_min=' + encodeURIComponent(args.bedrooms_min));
if (args.has_pool) queryParts.push('has_pool=true');
if (args.has_parking) queryParts.push('has_parking=true');
if (args.has_garden) queryParts.push('has_garden=true');

const queryString = queryParts.join('&');

const prevNodeData = $('Build Prompt').item.json;

return {
  json: {
    needs_tool_call: true,
    tool_args: args,
    query_string: queryString,
    original_user_message: prevNodeData.user_message,
    session_id: prevNodeData.session_id
  }
};

const searchResults = $json; // résultat brut de l'API Django
const prevData = $('extraire les arguments du functionCall').item.json;

const annonces = searchResults.results || searchResults;
const annoncesArray = Array.isArray(annonces) ? annonces : [];

const toolResultSummary = {
  count: annoncesArray.length,
  annonces: annoncesArray.slice(0, 5).map(a => ({
    id: a.id,
    title: a.title,
    city: a.city,
    price: a.price,
    property_type: a.property_type,
    bedrooms: a.bedrooms,
    has_pool: a.has_pool
  }))
};

// Les ids des annonces trouvées, pour les renvoyer au frontend (recommended_annonce_ids)
const annonceIds = annoncesArray.slice(0, 5).map(a => a.id);

return {
  json: {
    tool_result_summary: toolResultSummary,
    original_user_message: prevData.original_user_message,
    annonce_ids: annonceIds,
    session_id: prevData.session_id
  }
};

const prevData = $json; // tool_result_summary + original_user_message

const systemPrompt = `Tu es l'agent de recherche immobilière de Darimmo.

Voici le résultat de la recherche effectuée dans la base de données :
${JSON.stringify(prevData.tool_result_summary)}

Message original de l'utilisateur : "${prevData.original_user_message}"

Règles strictes :
- Base ta réponse UNIQUEMENT sur les résultats fournis ci-dessus. N'invente aucune annonce.
- Si count est 0, dis clairement qu'aucun bien ne correspond aux critères, et suggère d'élargir la recherche (ville voisine, budget plus large, ou retirer un critère comme la piscine).
- Si des annonces sont trouvées, présente-les brièvement (titre, ville, prix) en langage naturel, clair et concis.
- Reponds TOUJOURS dans la meme langue que le message de l'utilisateur. Si l'utilisateur ecrit en darija (arabe marocain, en caracteres latins ou arabes), en arabe standard, en francais ou en anglais, reponds dans cette meme langue.`;

return {
  json: {
    gemini_request_body: {
      contents: [
        { role: "user", parts: [{ text: systemPrompt }] }
      ]
    },
    session_id: prevData.session_id
  }
};

const body = $json.body || $json;
const userMessage = body.message;
const sessionId = body.session_id || 'unknown';
const userContext = body.user_context || {};
const authToken = body.auth_token || '';

const systemPrompt = `Tu es l'agent de recherche immobilière de Darimmo, une plateforme marocaine d'annonces immobilières.

Ton rôle : aider l'utilisateur à trouver des annonces réelles publiées sur Darimmo, en utilisant tes outils. Tu ne connais AUCUNE annonce par toi-même — toute information sur un bien doit provenir du résultat d'un outil.

Règles strictes :
- Utilise l'outil search_property pour chercher les annonces.
- Si aucun paramètre minimal n'est fourni (ni ville, ni type de bien, ni budget), pose une question de clarification au lieu d'appeler l'outil.
- Si l'outil renvoie une liste vide, dis-le clairement. Ne suggère jamais une annonce qui ne vient pas du résultat de l'outil.
- Réponds en langage naturel, clair et concis, en citant le nombre de résultats trouvés.
-Reponds TOUJOURS dans la meme langue que le message de l'utilisateur. Si l'utilisateur ecrit en darija (arabe marocain, en caracteres latins ou arabes), en arabe standard, en francais ou en anglais, reponds dans cette meme langue.`;

const toolDeclaration = {
  name: "search_property",
  description: "Recherche des annonces immobilières publiées sur Darimmo selon des critères structurés.",
  parameters: {
    type: "OBJECT",
    properties: {
      city: { type: "STRING", description: "Ville recherchée" },
      property_type: { type: "STRING", enum: ["villa","appartement","riad","maison","terrain"] },
      transaction_type: { type: "STRING", enum: ["vente","location"] },
      price_max: { type: "NUMBER" },
      price_min: { type: "NUMBER" },
      bedrooms_min: { type: "NUMBER" },
      has_pool: { type: "BOOLEAN" },
      has_parking: { type: "BOOLEAN" },
      has_garden: { type: "BOOLEAN" }
    }
  }
};

return {
  json: {
    user_message: userMessage,
    session_id: sessionId,
    user_context: userContext,
    auth_token: authToken,
    gemini_request_body: {
      contents: [
        { role: "user", parts: [{ text: `${systemPrompt}\n\nMessage de l'utilisateur : "${userMessage}"` }] }
      ],
      tools: [{ functionDeclarations: [toolDeclaration] }]
    }
  }
};

const replyText = $json.candidates[0].content.parts[0].text;
const annonceIds = $('reformater le résultat pour le renvoyer à Gemini').item.json.annonce_ids;
const sessionId = $json.session_id;

const FRONTEND_URL = 'http://localhost:5173';
const annonceLinks = (annonceIds || []).map(id => `${FRONTEND_URL}/annonces/${id}`);

// Ajoute les liens a la fin du texte de reponse, un par annonce.
let finalReply = replyText;
if (annonceLinks.length > 0) {
  const linksText = annonceLinks.map((link, i) => `Lien : ${link}`).join('\n');
  finalReply = `${replyText}\n\n${linksText}`;
}

return {
  json: {
    reply: finalReply,
    session_id: sessionId,
    recommended_annonce_ids: annonceIds || [],
    intent: "search_property",
    metadata: {
      agent_used: "property_search_agent",
      tool_calls_count: 1,
      llm_calls_count: 2
    }
  }
};
